import{_ as l,o as t,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"龙鹿（鹿族高层）","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/龙鹿.md","filePath":"中层/人物/龙鹿.md","lastUpdated":null}'),i={name:"中层/人物/龙鹿.md"};function n(s,r,e,g,h,u){return t(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="龙鹿-鹿族高层" tabindex="-1">龙鹿（鹿族高层） <a class="header-anchor" href="#龙鹿-鹿族高层" aria-label="Permalink to &quot;龙鹿（鹿族高层）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称</strong>：通常称为&quot;龙鹿&quot;，真实龙族名未知</li><li><strong>种族</strong>：表面为鹿族，实为龙族意识寄居于鹿族躯体</li><li><strong>身份</strong>：鹿族高层领袖之一，隐藏的反抗者</li><li><strong>时代</strong>：当前时代（共同体覆灭后至今）</li><li><strong>所在地</strong>：鹿国核心区域</li><li><strong>状态</strong>：活跃，但隐藏真实身份</li><li><strong>核心动机</strong>：毁灭被神明操控的世界，让一切回归&quot;原本的样子&quot;</li></ul><h2 id="外貌特征" tabindex="-1">外貌特征 <a class="header-anchor" href="#外貌特征" aria-label="Permalink to &quot;外貌特征&quot;">​</a></h2><h3 id="鹿族化身形体" tabindex="-1">鹿族化身形体 <a class="header-anchor" href="#鹿族化身形体" aria-label="Permalink to &quot;鹿族化身形体&quot;">​</a></h3><p>被古斯塔夫改造后，龙鹿拥有鹿族的外形特征：</p><ul><li><strong>毛色</strong>：<strong>灰毛</strong>，与古斯塔夫为自己捏造躯体的视觉特征一致</li><li><strong>眼睛</strong>：<strong>蓝色眼睛</strong>，同样与古斯塔夫的化身特征一致</li><li><strong>体型</strong>：标准的鹿族体型，便于融入鹿族社会</li><li><strong>外观印象</strong>：外表与普通鹿族无异，没有任何明显的龙族特征</li><li><strong>隐藏特性</strong>：外表完全掩盖了内部的龙族意识和本质</li></ul><h3 id="改造痕迹" tabindex="-1">改造痕迹 <a class="header-anchor" href="#改造痕迹" aria-label="Permalink to &quot;改造痕迹&quot;">​</a></h3><ul><li><strong>躯体匹配</strong>：躯体是古斯塔夫为自己准备的未完成鹿族躯体</li><li><strong>意识适应</strong>：龙族意识需要适应鹿族的生理结构和限制</li><li><strong>伪装完美</strong>：外部观察难以发现其真实身份</li></ul><h2 id="真实身份与改造" tabindex="-1">真实身份与改造 <a class="header-anchor" href="#真实身份与改造" aria-label="Permalink to &quot;真实身份与改造&quot;">​</a></h2><h3 id="龙族本质" tabindex="-1">龙族本质 <a class="header-anchor" href="#龙族本质" aria-label="Permalink to &quot;龙族本质&quot;">​</a></h3><p>龙鹿原本的身份是<strong>龙族</strong>：</p><ul><li><strong>原始身份</strong>：作为曾经的龙族，以及为数不多的真正见过神明的存在，其相比普通鹿族知晓更多真相</li><li><strong>反抗性格</strong>：因反抗龙族内部的压迫与统治而引发动乱，现转为反抗神明的压迫与统治而试图让世界“回归真实”</li><li><strong>龙族关系</strong>：作为头号反抗分子，曾在龙族内部具有一定影响力</li></ul><h3 id="改造过程" tabindex="-1">改造过程 <a class="header-anchor" href="#改造过程" aria-label="Permalink to &quot;改造过程&quot;">​</a></h3><p>因反抗行为引发危机，古斯塔夫被迫进行改造：</p><p><strong>改造原因</strong>：</p><ul><li><strong>动乱威胁</strong>：龙鹿的动乱引发强烈魔法波动，瞬间惊动了神明</li><li><strong>危机掩盖</strong>：古斯塔夫需要掩盖事态，保护龙族整体</li><li><strong>紧急处理</strong>：为避免维斯塔等神明以龙族内部的危机为理由，清理整个龙族</li></ul><p><strong>改造步骤</strong>：</p><ol><li><strong>宏量子屏障</strong>：古斯塔夫使用宏量子能力暂时屏蔽区域</li><li><strong>意识抽离</strong>：暴力将龙鹿的意识从龙族躯体中抽出</li><li><strong>躯体移植</strong>：将意识塞入为自己准备的未完成鹿族躯体中</li><li><strong>身份伪装</strong>：成为&quot;寄居于鹿族躯体的龙族&quot;</li></ol><h3 id="改造结果" tabindex="-1">改造结果 <a class="header-anchor" href="#改造结果" aria-label="Permalink to &quot;改造结果&quot;">​</a></h3><ul><li><strong>新身份</strong>：以鹿族身份重新开始</li><li><strong>限制条件</strong>：失去了原本的龙族躯体能力</li><li><strong>生存挑战</strong>：需要在鹿族社会中重新建立地位</li><li><strong>隐藏成功</strong>：成功避免了神明的察觉和惩罚</li></ul><h2 id="重要经历" tabindex="-1">重要经历 <a class="header-anchor" href="#重要经历" aria-label="Permalink to &quot;重要经历&quot;">​</a></h2><h3 id="改造后的初期" tabindex="-1">改造后的初期 <a class="header-anchor" href="#改造后的初期" aria-label="Permalink to &quot;改造后的初期&quot;">​</a></h3><ul><li><strong>量子屏障解除</strong>：改造完成后，量子屏障解除</li><li><strong>亲眼见证</strong>：以鹿族身份亲眼见证维斯塔对龙族的仇视打压</li><li><strong>反差体验</strong>：同时体验到维斯塔对&quot;鹿族子民&quot;身份的百般呵护</li><li><strong>本质认知</strong>：这种极端的种族待遇反差让其看清神明的&quot;双标&quot;本质</li></ul><h3 id="古斯塔夫的掩护" tabindex="-1">古斯塔夫的掩护 <a class="header-anchor" href="#古斯塔夫的掩护" aria-label="Permalink to &quot;古斯塔夫的掩护&quot;">​</a></h3><ul><li><strong>谎言掩护</strong>：古斯塔夫向维斯塔撒谎，称龙鹿是&quot;被龙族劫持的普通鹿族子民&quot;</li><li><strong>安全离开</strong>：龙鹿因此得以安全离开龙族隐居地</li><li><strong>新生活开始</strong>：作为黑户，从完全陌生的鹿族社会中一步步挣扎求生</li></ul><h3 id="鹿族社会崛起" tabindex="-1">鹿族社会崛起 <a class="header-anchor" href="#鹿族社会崛起" aria-label="Permalink to &quot;鹿族社会崛起&quot;">​</a></h3><ul><li><strong>艰难求生</strong>：初期在鹿族社会中艰难求生</li><li><strong>智慧运用</strong>：凭借龙族的智慧与不屈的意志逐渐站稳脚跟</li><li><strong>资源利用</strong>：利用鹿族的科技资源发展自己</li><li><strong>政治崛起</strong>：最终在鹿族社会中崛起，成为顶尖领袖之一</li><li><strong>身份隐藏</strong>：始终隐藏真实身份，避免被识破</li></ul><h3 id="持续隐藏" tabindex="-1">持续隐藏 <a class="header-anchor" href="#持续隐藏" aria-label="Permalink to &quot;持续隐藏&quot;">​</a></h3><ul><li><strong>谨慎行事</strong>：始终避免与维斯塔、神机等存在正面接触</li><li><strong>身份保护</strong>：采取各种措施保护自己的真实身份</li><li><strong>战略布局</strong>：在鹿族高层中进行战略布局</li></ul><h2 id="核心执念" tabindex="-1">核心执念 <a class="header-anchor" href="#核心执念" aria-label="Permalink to &quot;核心执念&quot;">​</a></h2><h3 id="执念内容" tabindex="-1">执念内容 <a class="header-anchor" href="#执念内容" aria-label="Permalink to &quot;执念内容&quot;">​</a></h3><p><strong>毁灭这个被神明操控的世界，让一切回归&quot;原本的样子&quot;</strong></p><h3 id="执念来源" tabindex="-1">执念来源 <a class="header-anchor" href="#执念来源" aria-label="Permalink to &quot;执念来源&quot;">​</a></h3><ol><li><strong>亲身经历</strong>：亲眼见证神明的种族双标待遇</li><li><strong>个人不公</strong>：自身被贬谪、改造的不公经历</li><li><strong>本质洞察</strong>：对世界运行逻辑的绝望认知</li><li><strong>系统反抗</strong>：认识到神明体系对整个世界的操控本质</li></ol><h3 id="执念特点" tabindex="-1">执念特点 <a class="header-anchor" href="#执念特点" aria-label="Permalink to &quot;执念特点&quot;">​</a></h3><ul><li><strong>深刻彻底</strong>：不是简单的复仇，而是对整个系统的反抗</li><li><strong>目标宏大</strong>：旨在改变世界的根本运行逻辑</li><li><strong>理性基础</strong>：基于对神明体系和叙事层的深入理解</li><li><strong>情感驱动</strong>：同时包含深刻的情感创伤和理性认知</li></ul><h2 id="能力与策略" tabindex="-1">能力与策略 <a class="header-anchor" href="#能力与策略" aria-label="Permalink to &quot;能力与策略&quot;">​</a></h2><h3 id="能力特点" tabindex="-1">能力特点 <a class="header-anchor" href="#能力特点" aria-label="Permalink to &quot;能力特点&quot;">​</a></h3><p>龙鹿不依赖靠不住的魔法天赋，而是采用更实际的策略：</p><p><strong>核心优势</strong>：</p><ul><li><strong>龙族见识</strong>：拥有龙族的古老知识和智慧底蕴</li><li><strong>科技资源</strong>：利用鹿国的科研资源和技术优势</li><li><strong>生物研究</strong>：秘密进行的<strong>生物科学研究</strong></li><li><strong>政治地位</strong>：作为鹿族高层的政治影响力和资源调动能力</li></ul><h3 id="生物研究" tabindex="-1">生物研究 <a class="header-anchor" href="#生物研究" aria-label="Permalink to &quot;生物研究&quot;">​</a></h3><p><strong>重塑龙躯计划</strong>：</p><ul><li><strong>研究目标</strong>：尝试重塑龙躯，重获龙族的力量</li><li><strong>技术路线</strong>：通过<strong>生物科学</strong>进行躯体克隆，与龙族捏造化身的&quot;概念性魔法打包&quot;并非同一技术体系</li><li><strong>资源利用</strong>：利用了鹿国的先进科研资源</li><li><strong>进展状态</strong>：准备中，稳步推进</li></ul><h3 id="上位毁灭神权继承线" tabindex="-1">上位毁灭神权继承线 <a class="header-anchor" href="#上位毁灭神权继承线" aria-label="Permalink to &quot;上位毁灭神权继承线&quot;">​</a></h3><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><ul><li>上位毁灭神权谱系中，正传以<strong>龙鹿寻得继承</strong>为关键线（详见 <a href="./../世界/神机谋划">神机谋划</a> 的毁灭神权谱系）</li><li><strong>鹿国线结局</strong>：在一系列事件后，龙鹿内心的灭世执念被化解，放弃寻找上位毁灭神权，成为和平的关键一环</li><li><strong>熊国线结局</strong>：若无人阻止，龙鹿通过秘密的生物研究成功为自己<strong>重塑龙躯</strong>，变回真龙，并<strong>继承了上位毁灭神权</strong>，开始灭世进程</li></ul><h2 id="与各方关系" tabindex="-1">与各方关系 <a class="header-anchor" href="#与各方关系" aria-label="Permalink to &quot;与各方关系&quot;">​</a></h2><h3 id="与龙族的关系" tabindex="-1">与龙族的关系 <a class="header-anchor" href="#与龙族的关系" aria-label="Permalink to &quot;与龙族的关系&quot;">​</a></h3><ul><li><strong>知晓存在</strong>：知晓龙王与龙族隐居地的存在</li><li><strong>避免联系</strong>：为了防止被神明察觉，没有与龙族保持任何联系</li><li><strong>情感复杂</strong>：对龙族既有归属感，又有因改造而产生的疏离感</li><li><strong>潜在支持</strong>：在暗中关注龙族的处境</li></ul><h3 id="与古斯塔夫的关系" tabindex="-1">与古斯塔夫的关系 <a class="header-anchor" href="#与古斯塔夫的关系" aria-label="Permalink to &quot;与古斯塔夫的关系&quot;">​</a></h3><ul><li><strong>改造者</strong>：古斯塔夫是改造龙鹿的存在</li><li><strong>救命恩人</strong>：在危机中救了龙鹿的性命</li><li><strong>复杂情感</strong>：曾经因其对龙族的压迫而仇视与不解，现在知晓原因后，既有感激，也有对龙族现状，与自己被改造的复杂感受</li></ul><h3 id="与神明的态度" tabindex="-1">与神明的态度 <a class="header-anchor" href="#与神明的态度" aria-label="Permalink to &quot;与神明的态度&quot;">​</a></h3><ul><li><strong>维斯塔</strong>：深刻认知其双标本质，极度警惕和敌视</li><li><strong>神机</strong>：始终避免与维斯塔、神机等存在正面接触，以防被识破</li><li><strong>总体态度</strong>：对所有神明持怀疑和反抗态度</li></ul><h3 id="在鹿族的地位" tabindex="-1">在鹿族的地位 <a class="header-anchor" href="#在鹿族的地位" aria-label="Permalink to &quot;在鹿族的地位&quot;">​</a></h3><ul><li><strong>高层领袖</strong>：在鹿族社会中具有重要地位</li><li><strong>表面忠诚</strong>：表面上对鹿族和鹿国忠诚，实际利用鹿族资源实现自己的目标</li><li><strong>影响力</strong>：能够调动鹿族的部分资源和力量</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/龙鹿" class="layer-link" data-layer="表层">龙鹿（表层档案）</a></li><li><a href="./../世界/龙族真相">龙族真相</a></li><li><a href="./古斯塔夫">古斯塔夫</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../../表层/种族/鹿族" class="layer-link" data-layer="表层">鹿族</a></li><li><a href="./../../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></li><li><a href="./../../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></li></ul><hr>',61)])])}const q=l(i,[["render",n]]);export{c as __pageData,q as default};
